public class HashMapInternalsDemo {
    public static void main(String[] args) {
        // Creating a map with a custom initial capacity and load factor
        Map<String, Integer> customMap = new HashMap<>(32, 0.75f);

        customMap.put("Engine", 1);
        customMap.put("Transmission", 2);

        // Retrieving a value triggers hash computation, bucket lookup, 
        // and potentially traversing a linked list or tree node.
        int val = customMap.get("Engine");
        System.out.println("Retrieved value: " + val);
    }
}
